/**
 * Generates extension/default.css — the static stylesheet declared in
 * the manifest, injected before any DOM is displayed (ADR-0001).
 * Generated from the same catalogue as the runtime CSS via
 * compileCss(DEFAULT_SETTINGS): one catalogue, two uses.
 * Do not edit the output by hand; run `npm run generate:css`.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { compileCss, DEFAULT_SETTINGS } from "../src/engine/blur-engine.js";

export const GENERATED_HEADER =
  "/* WA Blur — generated by scripts/generate-static-css.ts. Do not edit. */\n";

/**
 * Scopes every rule to `:root:not(.wa-blur-live)`. The static sheet
 * must govern only until the runtime's first apply (which puts the
 * LIVE_CLASS on <html>): scoped this way it disables itself instead of
 * fighting the runtime CSS on cascade order — an "off" Settings state
 * compiles to empty CSS and has nothing to override with
 * (ticket 01 code-review, Spec axis finding c).
 */
export function scopeToPreRuntime(css: string): string {
  return css
    .split("\n")
    .filter((line) => line.length > 0)
    .map((line) => line.replace(/^([^{]+)/, ":root:not(.wa-blur-live) $1"))
    .join("\n");
}

export function renderStaticCss(): string {
  return GENERATED_HEADER + scopeToPreRuntime(compileCss(DEFAULT_SETTINGS)) + "\n";
}

// Generate only when run as a script — importing this module (tests do,
// for GENERATED_HEADER) must not rewrite the file it is checking.
const invokedAsScript =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(process.argv[1]).href;

if (invokedAsScript) {
  const out = fileURLToPath(new URL("../extension/default.css", import.meta.url));
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, renderStaticCss());
  console.log(`wrote ${out}`);
}
